<?php require __DIR__.'/auth/bootstrap.php';require __DIR__.'/v1_nav.php';$userId=requireUser();$q=$pdo->prepare("SELECT t.*,us.nickname,us.custom_brand,us.custom_model FROM tags t LEFT JOIN user_shoes us ON us.id=t.user_shoe_id WHERE t.owner_user_id=? ORDER BY t.id DESC");$q->execute([$userId]);$rows=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tags — TOETAP</title><link rel="stylesheet" href="assets/v1.css"></head><body><main class="app"><div class="top"><div class="brand">TOETAP<i></i></div><a class="avatar" href="settings.php">G</a></div><div class="kicker">YOUR HARDWARE</div><?php if(($_GET['released']??'')==='1'):?><div class="notice">✓ Tag released. It is now unclaimed and ready for a new owner.</div><?php endif;?><div class="notice">Tap the physical NFC tag anytime to check which shoe it currently selects.</div><h1 class="pageTitle">TOETAP tags.</h1><?php if(currentUserIsAdmin()):?><div style="margin:-4px 0 14px"><a href="admin_tags.php" style="display:inline-block;text-decoration:none;background:#111;color:#c9ff54;border-radius:999px;padding:9px 12px;font-size:10px;font-weight:900">TAG INVENTORY →</a></div><?php endif;?><?php foreach($rows as $t):$nm=$t['nickname']?:trim(($t['custom_brand']??'').' '.($t['custom_model']??''));?><a href="tag_manage.php?id=<?=$t['id']?>" style="text-decoration:none;color:inherit"><div class="tagcard"><div class="tagid"><?=htmlspecialchars($t['tag_code'])?></div><div class="tagshoe"><?=htmlspecialchars($nm?:'Ready to activate')?></div><div class="tagstatus"><span class="dot"></span><?=htmlspecialchars($t['activation_status'])?></div></div></a><?php endforeach;?><div class="card"><div class="kicker">PASSIVE NFC</div><p style="font-size:13px;line-height:1.55;color:#777;margin-bottom:0">A TOETAP tag selects a shoe. No battery, GPS or location tracking.</p></div><?php if(currentUserIsAdmin()):?><a class="fab" href="tag_new.php" title="Admin: issue NFC tag">＋</a><?php endif;?><?php v1nav('tags');?></main></body></html>